CREATE SCHEMA IF NOT EXISTS monetization;
CREATE TABLE monetization.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),code varchar(64) NOT NULL,kind text NOT NULL CHECK(kind IN('bump','urgent','featured','storefront','package','subscription')),title varchar(120) NOT NULL,description varchar(500) NOT NULL,audience text NOT NULL DEFAULT 'all' CHECK(audience IN('personal','business','all')),duration_minutes integer NOT NULL DEFAULT 0 CHECK(duration_minutes BETWEEN 0 AND 525600),quota integer NOT NULL DEFAULT 1 CHECK(quota BETWEEN 1 AND 10000),sort_order integer NOT NULL DEFAULT 100,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','active','retired')),metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,code));
CREATE TABLE monetization.price_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),product_id uuid NOT NULL REFERENCES monetization.products(id),version integer NOT NULL CHECK(version>0),amount bigint NOT NULL CHECK(amount>0),currency char(3) NOT NULL DEFAULT 'IRR' CHECK(currency='IRR'),tax_bps integer NOT NULL DEFAULT 0 CHECK(tax_bps BETWEEN 0 AND 10000),state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','published','retired')),starts_at timestamptz NOT NULL,ends_at timestamptz,created_by uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(ends_at IS NULL OR ends_at>starts_at),UNIQUE(product_id,version));
CREATE UNIQUE INDEX monetization_active_price_idx ON monetization.price_versions(product_id)WHERE state='published'AND ends_at IS NULL;
CREATE FUNCTION monetization.reject_published_price_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.state='published'THEN RAISE EXCEPTION 'monetization_published_price_immutable';END IF;IF TG_OP='DELETE'THEN RETURN OLD;END IF;RETURN NEW;END$$;CREATE TRIGGER monetization_price_immutable BEFORE UPDATE OR DELETE ON monetization.price_versions FOR EACH ROW EXECUTE FUNCTION monetization.reject_published_price_mutation();
CREATE TABLE monetization.coupons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),code varchar(32) NOT NULL,kind text NOT NULL CHECK(kind IN('fixed','percentage')),value bigint NOT NULL CHECK(value>0),minimum_amount bigint NOT NULL DEFAULT 0 CHECK(minimum_amount>=0),maximum_discount bigint,usage_limit integer,used_count integer NOT NULL DEFAULT 0 CHECK(used_count>=0),per_user_limit integer NOT NULL DEFAULT 1 CHECK(per_user_limit BETWEEN 1 AND 100),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','active','paused','expired')),rules jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(ends_at>starts_at),CHECK(maximum_discount IS NULL OR maximum_discount>0),CHECK(kind<>'percentage'OR(value<=10000 AND maximum_discount IS NOT NULL)),CHECK(usage_limit IS NULL OR usage_limit>0),CHECK(usage_limit IS NULL OR used_count<=usage_limit),UNIQUE(tenant_id,code));
CREATE TABLE monetization.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),user_id uuid NOT NULL REFERENCES identity.users(id),business_id uuid,listing_id uuid REFERENCES listing.posts(id),idempotency_key varchar(120) NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','paid','fulfilled','partially_fulfilled','cancelled','refunded','failed')),subtotal bigint NOT NULL CHECK(subtotal>=0),discount bigint NOT NULL DEFAULT 0 CHECK(discount>=0),tax bigint NOT NULL DEFAULT 0 CHECK(tax>=0),total bigint NOT NULL CHECK(total>=0),currency char(3) NOT NULL DEFAULT 'IRR' CHECK(currency='IRR'),coupon_code varchar(32),payment_intent_id uuid REFERENCES finance.payment_intents(id),paid_at timestamptz,fulfilled_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(total=subtotal-discount+tax),CHECK(discount<=subtotal),UNIQUE(tenant_id,idempotency_key));
CREATE INDEX monetization_order_user_idx ON monetization.orders(tenant_id,user_id,created_at DESC);CREATE INDEX monetization_order_pending_idx ON monetization.orders(tenant_id,state,created_at)WHERE state='pending';
CREATE TABLE monetization.order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),order_id uuid NOT NULL REFERENCES monetization.orders(id)ON DELETE RESTRICT,product_id uuid NOT NULL REFERENCES monetization.products(id),price_version_id uuid NOT NULL REFERENCES monetization.price_versions(id),quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 100),unit_amount bigint NOT NULL CHECK(unit_amount>0),total_amount bigint NOT NULL CHECK(total_amount=unit_amount*quantity),metadata jsonb NOT NULL DEFAULT '{}',UNIQUE(order_id,product_id));
CREATE TABLE monetization.coupon_redemptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),coupon_id uuid NOT NULL REFERENCES monetization.coupons(id),order_id uuid NOT NULL REFERENCES monetization.orders(id),user_id uuid NOT NULL REFERENCES identity.users(id),discount bigint NOT NULL CHECK(discount>0),redeemed_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(coupon_id,order_id));CREATE INDEX monetization_coupon_user_idx ON monetization.coupon_redemptions(tenant_id,coupon_id,user_id);
CREATE TABLE monetization.entitlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),user_id uuid NOT NULL REFERENCES identity.users(id),business_id uuid,order_item_id uuid NOT NULL REFERENCES monetization.order_items(id),product_id uuid NOT NULL REFERENCES monetization.products(id),granted integer NOT NULL CHECK(granted>0),consumed integer NOT NULL DEFAULT 0 CHECK(consumed>=0),starts_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz,state text NOT NULL DEFAULT 'active' CHECK(state IN('pending','active','exhausted','expired','revoked')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(consumed<=granted),CHECK(expires_at IS NULL OR expires_at>starts_at),UNIQUE(order_item_id));CREATE INDEX monetization_entitlement_available_idx ON monetization.entitlements(tenant_id,user_id,product_id,expires_at)WHERE state='active';
CREATE TABLE monetization.entitlement_usage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),entitlement_id uuid NOT NULL REFERENCES monetization.entitlements(id),listing_id uuid REFERENCES listing.posts(id),amount integer NOT NULL DEFAULT 1 CHECK(amount>0),idempotency_key varchar(120) NOT NULL,used_at timestamptz NOT NULL DEFAULT clock_timestamp(),metadata jsonb NOT NULL DEFAULT '{}',UNIQUE(tenant_id,idempotency_key));
CREATE TABLE monetization.promotions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),listing_id uuid NOT NULL REFERENCES listing.posts(id),user_id uuid NOT NULL REFERENCES identity.users(id),entitlement_id uuid NOT NULL REFERENCES monetization.entitlements(id),kind text NOT NULL CHECK(kind IN('bump','urgent','featured')),state text NOT NULL DEFAULT 'scheduled' CHECK(state IN('scheduled','active','completed','cancelled','failed')),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,activated_at timestamptz,completed_at timestamptz,idempotency_key varchar(120) NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(ends_at>starts_at),UNIQUE(tenant_id,idempotency_key));CREATE INDEX monetization_promotion_schedule_idx ON monetization.promotions(tenant_id,state,starts_at,ends_at)WHERE state IN('scheduled','active');
CREATE TABLE monetization.subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),user_id uuid NOT NULL REFERENCES identity.users(id),business_id uuid,product_id uuid NOT NULL REFERENCES monetization.products(id),order_id uuid NOT NULL REFERENCES monetization.orders(id),state text NOT NULL DEFAULT 'active' CHECK(state IN('trialing','active','past_due','paused','cancelled','expired')),starts_at timestamptz NOT NULL,current_period_end timestamptz NOT NULL,cancel_at_period_end boolean NOT NULL DEFAULT false,renewal_key varchar(120) NOT NULL,next_attempt_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(current_period_end>starts_at),UNIQUE(order_id),UNIQUE(tenant_id,renewal_key));CREATE INDEX monetization_subscription_renewal_idx ON monetization.subscriptions(tenant_id,state,current_period_end)WHERE state IN('trialing','active','past_due');
CREATE TABLE monetization.revenue_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),order_id uuid NOT NULL REFERENCES monetization.orders(id),event_type text NOT NULL CHECK(event_type IN('recognized','deferred','refunded','chargeback')),amount bigint NOT NULL CHECK(amount>0),journal_id uuid REFERENCES finance.journal_entries(id),idempotency_key varchar(120) NOT NULL,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,idempotency_key));
DO $$DECLARE table_name text;BEGIN FOREACH table_name IN ARRAY ARRAY['products','price_versions','coupons','orders','order_items','coupon_redemptions','entitlements','entitlement_usage','promotions','subscriptions','revenue_events']LOOP EXECUTE format('ALTER TABLE monetization.%I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE monetization.%I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I ON monetization.%I USING(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)WITH CHECK(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)',table_name||'_tenant_isolation',table_name);END LOOP;END$$;
